export const config = { runtime: 'nodejs20.x' };

const EMAILJS_URL = 'https://api.emailjs.com/api/v1.0/email/send';
const TURNSTILE_VERIFY_URL = 'https://challenges.cloudflare.com/turnstile/v0/siteverify';

const INTEREST_OPTIONS = [
  'Culture & History', 'Luxury', 'Adventure', 'Desert Safari', 'Wellness',
  'Food Tours', 'Photography', 'Village Experiences', 'Festivals', 'Wildlife',
];
const DESTINATION_OPTIONS = [
  'Jaipur', 'Udaipur', 'Jodhpur', 'Jaisalmer', 'Pushkar', 'Ranthambore', 'Bikaner', 'Mount Abu',
];
const ACCOMMODATION_OPTIONS = ['heritage', 'luxury-resorts', 'boutique', 'camps'];

const MAX_NAME_LENGTH = 100;
const MAX_TEXT_LENGTH = 80;
const MAX_NOTES_LENGTH = 2000;
const MAX_PAYLOAD_BYTES = 1_000_000;

const RATE_LIMIT = 5;
const RATE_WINDOW_MS = 10 * 60 * 1000;
const rateBuckets = new Map();

const DEFAULT_ALLOWED_ORIGINS = 'https://dunexplore.com,https://www.dunexplore.com';

function json(res, status, body) {
  res.statusCode = status;
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify(body));
}

function clientIp(req) {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  return req.socket && req.socket.remoteAddress ? req.socket.remoteAddress : 'unknown';
}

function isRateLimited(ip) {
  const now = Date.now();
  const bucket = rateBuckets.get(ip);
  if (!bucket || bucket.resetAt <= now) {
    rateBuckets.set(ip, { count: 1, resetAt: now + RATE_WINDOW_MS });
    return false;
  }
  bucket.count += 1;
  return bucket.count > RATE_LIMIT;
}

function originAllowed(req) {
  const allowed = (process.env.ALLOWED_ORIGINS || DEFAULT_ALLOWED_ORIGINS)
    .split(',')
    .map((o) => o.trim().toLowerCase())
    .filter(Boolean);
  const origin = (req.headers.origin || '').toLowerCase();
  if (!origin) return true;
  return allowed.includes(origin);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    if (Buffer.isBuffer(req.body)) { resolve(req.body.toString('utf8')); return; }
    if (typeof req.body === 'string') { resolve(req.body); return; }
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > MAX_PAYLOAD_BYTES) {
        req.destroy(new Error('Payload too large'));
      }
    });
    req.on('end', () => resolve(raw));
    req.on('error', reject);
  });
}

function sanitizeString(value, maxLength) {
  if (typeof value !== 'string') return '';
  return value
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLength);
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
}

function isValidPhone(phone) {
  return /^\+?[\d\s\-()]{7,20}$/.test(phone);
}

function pickAllowed(value, allowed) {
  if (typeof value !== 'string') return '';
  return allowed.includes(value) ? value : '';
}

function pickArray(values, allowed, maxItems) {
  if (!Array.isArray(values)) return [];
  const picked = values
    .filter((v) => typeof v === 'string' && allowed.includes(v));
  return picked.slice(0, maxItems);
}

async function verifyTurnstile(token) {
  const secret = process.env.TURNSTILE_SECRET_KEY;
  if (!secret) return { required: false, ok: true };
  if (typeof token !== 'string' || !token) return { required: true, ok: false };
  const params = new URLSearchParams({ secret, response: token });
  const resp = await fetch(TURNSTILE_VERIFY_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
  });
  const data = await resp.json().catch(() => ({}));
  return { required: true, ok: data.success === true };
}

async function forwardToSheets(payload) {
  const url = process.env.GAS_SHEETS_URL;
  if (!url) return { status: 'skipped' };
  const headers = { 'content-type': 'application/json' };
  if (process.env.GAS_SHARED_TOKEN) headers['x-inquiry-token'] = process.env.GAS_SHARED_TOKEN;
  const resp = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload),
  });
  const text = await resp.text();
  try {
    const parsed = JSON.parse(text);
    return typeof parsed === 'object' && parsed !== null ? parsed : { status: 'error' };
  } catch {
    return { status: resp.ok ? 'success' : 'error', message: text.slice(0, 200) };
  }
}

async function forwardToEmail(isDuplicate, sanitized) {
  const serviceId = process.env.EMAILJS_SERVICE_ID;
  const templateId = process.env.EMAILJS_TEMPLATE_ID;
  const publicKey = process.env.EMAILJS_PUBLIC_KEY;
  if (!serviceId || !templateId || !publicKey) return { status: 'skipped' };

  const name = sanitized.name || 'Not provided';
  const subjectPrefix = isDuplicate ? '\u{1F501} Existing Customer Query' : '\u{1F195} New Customer Query';
  const params = {
    subject: `${subjectPrefix} \u2014 ${name}`,
    name,
    email: sanitized.email,
    whatsapp: sanitized.whatsapp,
    country: sanitized.country || 'Not provided',
    travel_dates: sanitized.travelDates || 'Not specified',
    travelers: sanitized.travelers || 'Not specified',
    accommodation: sanitized.accommodation || 'Not specified',
    interests: sanitized.interests.join(', ') || 'None selected',
    destinations: sanitized.destinations.join(', ') || 'None selected',
    notes: sanitized.notes || 'No special requests',
    timestamp: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
  };

  const resp = await fetch(EMAILJS_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      service_id: serviceId,
      template_id: templateId,
      user_id: publicKey,
      template_params: params,
    }),
  });
  const text = await resp.text();
  try {
    const parsed = JSON.parse(text);
    return typeof parsed === 'object' && parsed !== null ? parsed : { status: resp.ok ? 'success' : 'error' };
  } catch {
    return { status: resp.ok ? 'success' : 'error', message: text.slice(0, 200) };
  }
}

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return json(res, 405, { status: 'error', message: 'Method not allowed' });
  }
  if (!originAllowed(req)) {
    return json(res, 403, { status: 'error', message: 'Request origin not allowed' });
  }

  const ip = clientIp(req);
  if (isRateLimited(ip)) {
    return json(res, 429, { status: 'error', message: 'Too many requests. Please try again later.' });
  }

  let parsed;
  try {
    const raw = await readBody(req);
    parsed = JSON.parse(raw || '{}');
  } catch {
    return json(res, 400, { status: 'error', message: 'Invalid request body' });
  }

  const name = sanitizeString(parsed.name, MAX_NAME_LENGTH);
  const emailAddress = sanitizeString(parsed.email, 254).toLowerCase();
  const whatsapp = sanitizeString(parsed.whatsapp, 20);
  const country = sanitizeString(parsed.country, MAX_TEXT_LENGTH);
  const travelDates = sanitizeString(parsed.travelDates, MAX_TEXT_LENGTH);
  const notes = sanitizeString(parsed.notes, MAX_NOTES_LENGTH);
  const consent = parsed.consent === true;

  let travelers = '';
  if (typeof parsed.travelers === 'number' && Number.isInteger(parsed.travelers)
      && parsed.travelers >= 1 && parsed.travelers <= 100) {
    travelers = String(parsed.travelers);
  } else if (typeof parsed.travelers === 'string' && /^\d{1,3}$/.test(parsed.travelers.trim())
             && Number(parsed.travelers) >= 1 && Number(parsed.travelers) <= 100) {
    travelers = String(Number(parsed.travelers));
  }

  const accommodation = pickAllowed(parsed.accommodation, ACCOMMODATION_OPTIONS);
  const interests = pickArray(parsed.interests, INTEREST_OPTIONS, INTEREST_OPTIONS.length);
  const destinations = pickArray(parsed.destinations, DESTINATION_OPTIONS, DESTINATION_OPTIONS.length);

  if (!isValidEmail(emailAddress)) {
    return json(res, 400, { status: 'error', message: 'Please provide a valid email address.' });
  }
  if (!isValidPhone(whatsapp)) {
    return json(res, 400, { status: 'error', message: 'Please provide a valid phone number.' });
  }
  if (!consent) {
    return json(res, 400, { status: 'error', message: 'Consent is required before submitting.' });
  }

  const turnstile = await verifyTurnstile(parsed.turnstileToken);
  if (turnstile.required && !turnstile.ok) {
    return json(res, 400, { status: 'error', message: 'Security check failed. Please try again.' });
  }

  const sanitized = { name, email: emailAddress, whatsapp, country, travelDates, travelers, accommodation, interests, destinations, notes };

  const sheetsResult = await forwardToSheets(sanitized);
  const isDuplicate = sheetsResult.status === 'duplicate';
  const emailResult = await forwardToEmail(isDuplicate, sanitized);

  const sheets = sheetsResult && sheetsResult.status ? sheetsResult : { status: 'error', message: 'Sheets forward failed' };
  const email = emailResult && emailResult.status ? emailResult : { status: 'error', message: 'Email forward failed' };

  if (isDuplicate) {
    return json(res, 200, {
      status: 'duplicate',
      message: 'Welcome back! Your previous inquiry has been updated.',
      sheets,
      email,
    });
  }

  const failed = [sheets, email].filter((r) => r.status === 'error');
  if (failed.length > 0) {
    console.error('contact proxy: forward failures', JSON.stringify(failed));
    return json(res, 502, { status: 'error', message: 'Failed to deliver your inquiry. Please try again or contact us directly.', sheets, email });
  }

  return json(res, 200, { status: 'success', message: 'Inquiry received. We will contact you shortly.', sheets, email });
}

import React, { lazy, Suspense, useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import ScrollToTop from './components/ui/ScrollToTop';
import SkipLink from './components/ui/SkipLink';
import Preloader from './components/ui/Preloader';
import FloatingWhatsApp from './components/ui/FloatingWhatsApp';
import StickyMobileCta from './components/ui/StickyMobileCta';
import './App.css';

const Home = lazy(() => import('./pages/Home'));
const PlanJourney = lazy(() => import('./pages/PlanJourney'));
const Destinations = lazy(() => import('./pages/Destinations'));
const StyleDetail = lazy(() => import('./pages/StyleDetail'));
const ExperienceDetail = lazy(() => import('./pages/ExperienceDetail'));
const About = lazy(() => import('./pages/About'));
const Stories = lazy(() => import('./pages/Stories'));
const TermsAndConditions = lazy(() => import('./pages/TermsAndConditions'));
const PrivacyPolicy = lazy(() => import('./pages/PrivacyPolicy'));
const PaymentPolicy = lazy(() => import('./pages/PaymentPolicy'));
const NotFound = lazy(() => import('./pages/NotFound'));

function AnimatedRoutes() {
  const location = useLocation();
  return (
    <AnimatePresence mode="wait">
      <Routes location={location} key={location.pathname}>
        <Route path="/" element={<Home />} />
        <Route path="/plan-journey" element={<PlanJourney />} />
        <Route path="/destinations" element={<Destinations />} />
        <Route path="/styles/:styleId" element={<StyleDetail />} />
        <Route path="/experience/:id" element={<ExperienceDetail />} />
        <Route path="/about" element={<About />} />
        <Route path="/blog" element={<Stories />} />
        <Route path="/stories" element={<Stories />} />
        <Route path="/terms-and-conditions" element={<TermsAndConditions />} />
        <Route path="/privacy-policy" element={<PrivacyPolicy />} />
        <Route path="/payment-policy" element={<PaymentPolicy />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </AnimatePresence>
  );
}

function App() {
  const [isLoading, setIsLoading] = useState(true);
  const timerRef = useRef(null);

  useEffect(() => {
    timerRef.current = setTimeout(() => setIsLoading(false), 1600);
    return () => clearTimeout(timerRef.current);
  }, []);

  return (
    <Router>
      <Preloader isLoading={isLoading} />
      <SkipLink />
      <ScrollToTop />
      <div className="app">
        <Navbar />
        <main id="main-content">
          <Suspense fallback={<div className="route-fallback" />}>
            <AnimatedRoutes />
          </Suspense>
        </main>
        <Footer />
        <FloatingWhatsApp />
        <StickyMobileCta />
      </div>
    </Router>
  );
}

export default App;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, ChevronLeft, Send, CheckCircle, Loader } from 'lucide-react';
import { submitInquiry } from '../../services/contactService';
import Turnstile from './Turnstile';
import './MultiStepForm.css';

const MultiStepForm = () => {
  const [step, setStep] = useState(1);
  const totalSteps = 4;
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isDuplicate, setIsDuplicate] = useState(false);
  const [turnstileToken, setTurnstileToken] = useState(null);
  const [consent, setConsent] = useState(false);
  const [submitError, setSubmitError] = useState('');

  const [formData, setFormData] = useState({
    name: '', email: '', country: '', whatsapp: '',
    travelDates: '', travelers: '', accommodation: '',
    interests: [], destinations: [], notes: ''
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for the field being edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleCheckboxChange = (name, value) => {
    setFormData(prev => {
      const currentList = prev[name];
      if (currentList.includes(value)) {
        return { ...prev, [name]: currentList.filter(item => item !== value) };
      } else {
        return { ...prev, [name]: [...currentList, value] };
      }
    });
  };

  const validateStep = () => {
    const newErrors = {};

    if (step === 1) {
      if (!formData.email.trim()) {
        newErrors.email = 'Email address is required';
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
        newErrors.email = 'Please enter a valid email address';
      }

      if (!formData.whatsapp.trim()) {
        newErrors.whatsapp = 'WhatsApp number is required';
      } else if (!/^\+?[\d\s\-()]{7,15}$/.test(formData.whatsapp.trim())) {
        newErrors.whatsapp = 'Please enter a valid phone number';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const nextStep = () => {
    if (validateStep()) {
      if (step < totalSteps) setStep(step + 1);
    }
  };

  const prevStep = () => { if (step > 1) setStep(step - 1); };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitError('');

    if (!consent) {
      setErrors(prev => ({ ...prev, consent: 'Please agree to be contacted before submitting.' }));
      return;
    }

    setIsSubmitting(true);

    try {
      const result = await submitInquiry(formData, turnstileToken);

      if (result.status === 'success' || result.status === 'duplicate') {
        setIsDuplicate(result.status === 'duplicate');
        setIsSubmitted(true);
      } else if (result.httpStatus === 429) {
        setSubmitError('Too many requests. Please wait a few minutes and try again.');
      } else {
        setSubmitError(result.message || 'Something went wrong. Please try again or contact us directly.');
      }
    } catch (error) {
      console.error('Submission error:', error);
      setSubmitError('Something went wrong. Please try again or contact us directly.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetForm = () => {
    setFormData({
      name: '', email: '', country: '', whatsapp: '',
      travelDates: '', travelers: '', accommodation: '',
      interests: [], destinations: [], notes: ''
    });
    setStep(1);
    setIsSubmitted(false);
    setIsDuplicate(false);
    setErrors({});
    setConsent(false);
    setTurnstileToken(null);
    setSubmitError('');
  };

  const interestsOptions = ['Culture & History', 'Luxury', 'Adventure', 'Desert Safari', 'Wellness', 'Food Tours', 'Photography', 'Village Experiences', 'Festivals', 'Wildlife'];
  const destinationsOptions = ['Jaipur', 'Udaipur', 'Jodhpur', 'Jaisalmer', 'Pushkar', 'Ranthambore', 'Bikaner', 'Mount Abu'];

  const variants = {
    initial: { opacity: 0, x: 50 },
    animate: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: -50 }
  };

  // Success screen after submission
  if (isSubmitted) {
    return (
      <div className="multistep-form-container">
        <motion.div
          className="submission-success"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.5, ease: 'easeOut' }}
        >
          <motion.div
            className="success-icon"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring', stiffness: 200 }}
          >
            <CheckCircle size={64} aria-hidden="true" />
          </motion.div>

          {isDuplicate && (
            <div className="duplicate-banner">
              Welcome back! We've updated your previous inquiry with the latest details.
            </div>
          )}

          <h2>Thank You, {formData.name || 'Explorer'}!</h2>
          <p>
            Your travel inquiry has been received. Our team will reach out to you
            at <strong>{formData.email}</strong> or <strong>{formData.whatsapp}</strong> shortly.
          </p>
          <button className="btn btn-primary" onClick={resetForm} style={{ marginTop: '2rem' }}>
            Submit Another Inquiry
          </button>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="multistep-form-container">
      {/* Loading overlay */}
      {isSubmitting && (
        <div className="submit-loading" role="status">
          <Loader size={40} className="spinner" aria-hidden="true" />
          <p>Sending your inquiry...</p>
        </div>
      )}

      <div className="progress-bar" aria-hidden="true">
        <div className="progress-fill" style={{ width: `${(step / totalSteps) * 100}%` }}></div>
      </div>

      <div className="form-header">
        <span className="step-indicator">Step {step} of {totalSteps}</span>
        <h2>
          {step === 1 && "Let's Get to Know You"}
          {step === 2 && "Tell Us About Your Trip"}
          {step === 3 && "What Are Your Preferences?"}
          {step === 4 && "Any Special Requests?"}
        </h2>
      </div>

      <form onSubmit={handleSubmit} className="form-content">
        <AnimatePresence mode="wait">
          <motion.div
            key={step}
            variants={variants}
            initial="initial"
            animate="animate"
            exit="exit"
            transition={{ duration: 0.3 }}
          >
            {step === 1 && (
              <div className="form-grid">
                <div className="form-group">
                  <label className="form-label" htmlFor="form-name">Full Name</label>
                  <input type="text" className="form-control" id="form-name" name="name" value={formData.name} onChange={handleInputChange} />
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="form-email">Email Address <span className="mandatory-star" aria-hidden="true">*</span></label>
                  <input
                    type="email"
                    className={`form-control ${errors.email ? 'input-error' : ''}`}
                    id="form-email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="your@email.com"
                    aria-invalid={errors.email ? 'true' : 'false'}
                    aria-describedby={errors.email ? 'form-email-error' : undefined}
                  />
                  {errors.email && (
                    <span id="form-email-error" className="field-error" role="alert">{errors.email}</span>
                  )}
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="form-country">Country</label>
                  <input type="text" className="form-control" id="form-country" name="country" value={formData.country} onChange={handleInputChange} />
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="form-whatsapp">WhatsApp Number <span className="mandatory-star" aria-hidden="true">*</span></label>
                  <input
                    type="tel"
                    className={`form-control ${errors.whatsapp ? 'input-error' : ''}`}
                    id="form-whatsapp"
                    name="whatsapp"
                    value={formData.whatsapp}
                    onChange={handleInputChange}
                    placeholder="+91 98765 43210"
                    aria-invalid={errors.whatsapp ? 'true' : 'false'}
                    aria-describedby={errors.whatsapp ? 'form-whatsapp-error' : undefined}
                  />
                  {errors.whatsapp && (
                    <span id="form-whatsapp-error" className="field-error" role="alert">{errors.whatsapp}</span>
                  )}
                </div>
              </div>
            )}

            {step === 2 && (
              <div className="form-grid">
                <div className="form-group">
                  <label className="form-label" htmlFor="form-travel-dates">Expected Travel Dates</label>
                  <input type="text" className="form-control" id="form-travel-dates" placeholder="e.g. Nov 2026 or Exact Dates" name="travelDates" value={formData.travelDates} onChange={handleInputChange} />
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="form-travelers">Number of Travelers</label>
                  <input type="number" className="form-control" id="form-travelers" min="1" name="travelers" value={formData.travelers} onChange={handleInputChange} />
                </div>

                <div className="form-group">
                  <label className="form-label" htmlFor="form-accommodation">Accommodation Type</label>
                  <select className="form-control" id="form-accommodation" name="accommodation" value={formData.accommodation} onChange={handleInputChange}>
                    <option value="">Select Accommodation</option>
                    <option value="heritage">Heritage Hotels</option>
                    <option value="luxury-resorts">5-Star Luxury Resorts</option>
                    <option value="boutique">Boutique Stays</option>
                    <option value="camps">Luxury Desert Camps</option>
                  </select>
                </div>
              </div>
            )}

            {step === 3 && (
              <div className="preferences-section">
                <fieldset className="form-group">
                  <legend className="form-label">Travel Interests (Select Multiple)</legend>
                  <div className="checkbox-grid">
                    {interestsOptions.map(interest => (
                      <label key={interest} className={`checkbox-card ${formData.interests.includes(interest) ? 'selected' : ''}`}>
                        <input type="checkbox" onChange={() => handleCheckboxChange('interests', interest)} checked={formData.interests.includes(interest)} />
                        {interest}
                      </label>
                    ))}
                  </div>
                </fieldset>

                <fieldset className="form-group mt-lg">
                  <legend className="form-label">Preferred Destinations (Select Multiple)</legend>
                  <div className="checkbox-grid">
                    {destinationsOptions.map(dest => (
                      <label key={dest} className={`checkbox-card ${formData.destinations.includes(dest) ? 'selected' : ''}`}>
                        <input type="checkbox" onChange={() => handleCheckboxChange('destinations', dest)} checked={formData.destinations.includes(dest)} />
                        {dest}
                      </label>
                    ))}
                  </div>
                </fieldset>
              </div>
            )}

            {step === 4 && (
              <div className="form-group">
                <label className="form-label" htmlFor="form-notes">Additional Notes or Special Requirements</label>
                <textarea
                  className="form-control"
                  id="form-notes"
                  rows="6"
                  placeholder="Tell us about special occasions, dietary requirements, or specific experiences you're looking forward to..."
                  name="notes"
                  value={formData.notes}
                  onChange={handleInputChange}
                ></textarea>

                <div className="consent-row">
                  <input
                    type="checkbox"
                    id="form-consent"
                    name="consent"
                    checked={consent}
                    onChange={(e) => {
                      setConsent(e.target.checked);
                      if (errors.consent) setErrors(prev => ({ ...prev, consent: '' }));
                    }}
                    aria-invalid={errors.consent ? 'true' : 'false'}
                  />
                  <label className="consent-label" htmlFor="form-consent">
                    I agree to be contacted about my travel inquiry and consent to Dune Explorer
                    processing my details as described in the{' '}
